insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Desfaça primeiro a adição, mantendo a igualdade nos dois lados.','Operações inversas em equações de primeiro grau.','["Subtraia 6 dos dois lados: 3x = 15.","Divida por 3: x = 5."]'::jsonb,'["3 × 3 + 6 = 15, diferente de 21.","3 × 5 + 6 = 21: a igualdade é satisfeita.","Dividir 21 por 3 antes de retirar o 6 ignora uma parcela.","3 × 9 + 6 = 33, diferente de 21."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Operações inversas em equações de primeiro grau."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Quanto vale x na equação 3x + 6 = 21?'))) and statement='Quanto vale x na equação 3x + 6 = 21?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Calcule a parte correspondente ao desconto antes de subtraí-la do preço.','Porcentagem como fração de uma quantidade.','["15% de 200 são 30.","Portanto, 200 − 30 = R$ 170."]'::jsonb,'["Desconto de R$ 50 corresponde a 25%, não a 15%.","Desconto de R$ 35 corresponde a 17,5%.","O desconto é 0,15 × 200 = 30; o preço fica 170.","Subtrair 15 reais confunde porcentagem com valor monetário."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Porcentagem como fração de uma quantidade."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Um produto de R$ 200 recebe desconto de 15%. Qual é o preço final?'))) and statement='Um produto de R$ 200 recebe desconto de 15%. Qual é o preço final?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Busque dois números cujo produto e soma permitam fatorar o polinômio.','Fatoração e propriedade do produto nulo.','["A fatoração é (x − 2)(x − 3) = 0.","Assim, x = 2 ou x = 3."]'::jsonb,'["1 e 6 têm produto 6, mas soma 7; não geram o coeficiente −5.","(x − 2)(x − 3) reproduz o polinômio.","Raízes negativas gerariam o termo +5x.","Além dos sinais, a soma −7 não corresponde à soma das raízes."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Fatoração e propriedade do produto nulo."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Quais são as raízes de x² − 5x + 6 = 0?'))) and statement='Quais são as raízes de x² − 5x + 6 = 0?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Use a propriedade da soma de logaritmos e confira o domínio ao final.','Logaritmo de um produto e domínio de funções logarítmicas.','["Somando logaritmos: log₂(x² − 1) = 3.","Logo x² − 1 = 8, x² = 9.","No domínio x > 1, x = 3."]'::jsonb,'["Para x = 2, o produto (x − 1)(x + 1) é 3, não 8.","x² − 1 = 8 fornece x = ±3; o domínio permite apenas 3.","Para x = 4, o produto vale 15.","O valor 8 é o argumento após converter o logaritmo; ainda não é x."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Logaritmo de um produto e domínio de funções logarítmicas."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Se log₂(x − 1) + log₂(x + 1) = 3, com x > 1, qual é x?'))) and statement='Se log₂(x − 1) + log₂(x + 1) = 3, com x > 1, qual é x?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Conte quantos saltos separam o primeiro termo do décimo.','Termo geral de uma progressão aritmética.','["Use aₙ = a₁ + (n − 1)r: a₁₀ = 4 + 9 × 3 = 31."]'::jsonb,'["27 é apenas 9 vezes a razão; falta somar o primeiro termo.","28 não resulta de somar nove razões a 4.","Usar dez razões confunde posição com número de intervalos.","Há nove intervalos: 4 + 9 × 3 = 31."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Termo geral de uma progressão aritmética."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Uma progressão aritmética tem primeiro termo 4 e razão 3. Qual é o décimo termo?'))) and statement='Uma progressão aritmética tem primeiro termo 4 e razão 3. Qual é o décimo termo?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Transforme o módulo em uma desigualdade dupla e respeite os extremos abertos.','Inequação modular e contagem de números inteiros.','["−5 < 2x − 3 < 5 equivale a −1 < x < 4.","Os inteiros são 0, 1, 2 e 3: quatro números."]'::jsonb,'["Excluir também o zero deixa um inteiro válido de fora.","Os valores 0, 1, 2 e 3 satisfazem a desigualdade estrita.","Incluir um dos extremos −1 ou 4 viola o sinal de menor estrito.","Incluir ambos os extremos viola a desigualdade."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Inequação modular e contagem de números inteiros."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Quantos números inteiros x satisfazem |2x − 3| < 5?'))) and statement='Quantos números inteiros x satisfazem |2x − 3| < 5?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Encontre quem pratica a ação e identifique a palavra central desse grupo.','Núcleo nominal do sujeito.','["O sujeito é “As meninas”; seu núcleo é o substantivo “meninas”."]'::jsonb,'["“As” é artigo que acompanha o núcleo.","“Meninas” é o substantivo central do sujeito.","“Chegaram” é o verbo do predicado.","“Cedo” indica circunstância de tempo."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Núcleo nominal do sujeito."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Em “As meninas chegaram cedo”, qual termo é o núcleo do sujeito?'))) and statement='Em “As meninas chegaram cedo”, qual termo é o núcleo do sujeito?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Compare o sentido literal com uma imagem usada para expressar uma sensação.','Linguagem denotativa e conotativa.','["“Iluminou o dia” expressa uma sensação positiva em sentido figurado, não uma iluminação física."]'::jsonb,'["O horário de chegada está em sentido literal.","A fervura é descrita literalmente.","O sorriso não emite luz: “iluminou” expressa uma sensação.","A quantidade de páginas está em sentido literal."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Linguagem denotativa e conotativa."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Qual frase apresenta linguagem conotativa?'))) and statement='Qual frase apresenta linguagem conotativa?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Verifique se há encontro de preposição a com artigo feminino a.','Crase depende de regência e presença do artigo.','["O verbo entregar exige a preposição a para o destinatário.","Com o artigo a de “a professora”, ocorre à."]'::jsonb,'["“Pé” é masculino; a expressão é “a pé”.","Entregar a alguém + a professora resulta em “à professora”.","“Tempo” é masculino: “a tempo”.","Antes de verbo no infinitivo não há artigo feminino: “a estudar”."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Crase depende de regência e presença do artigo."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Qual alternativa emprega corretamente a crase?'))) and statement='Qual alternativa emprega corretamente a crase?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Pense se a chuva causa a saída ou se é um obstáculo que não a impediu.','Relação de concessão entre orações.','["A chuva é um obstáculo que não impediu a saída.","“Embora” introduz uma concessão."]'::jsonb,'["A saída não é apresentada como causada pela chuva.","Chover não é a finalidade da saída.","A ação ocorre apesar do obstáculo: concessão.","A chuva não aparece como consequência da saída."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Relação de concessão entre orações."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Em “Embora chovesse, saímos”, a oração introduzida por “embora” expressa:'))) and statement='Em “Embora chovesse, saímos”, a oração introduzida por “embora” expressa:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Diferencie verbos impessoais daqueles que concordam com um sujeito plural.','Concordância verbal e impessoalidade.','["O verbo existir concorda com “boas oportunidades”.","Fazer indicando tempo e haver no sentido de existir são impessoais."]'::jsonb,'["“Fazer” indicando tempo decorrido fica no singular: faz dois anos.","“Haver” com sentido de existir fica no singular: houve candidatos.","“Existir” tem sujeito plural e concorda com oportunidades.","No tempo composto, o auxiliar concorda: haviam chegado os alunos."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Concordância verbal e impessoalidade."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Qual frase apresenta concordância verbal correta?'))) and statement='Qual frase apresenta concordância verbal correta?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Tente reescrever a frase usando o verbo ser seguido de particípio.','Voz passiva sintética e sujeito paciente.','["A frase equivale a “Livros usados são vendidos”.","O sujeito paciente é “livros usados” e o se é apassivador."]'::jsonb,'["O sujeito é identificável: livros usados.","A frase equivale a “Livros usados são vendidos”.","Os livros não praticam sobre si mesmos a ação de vender.","O “se” não introduz uma oração subordinada substantiva."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Voz passiva sintética e sujeito paciente."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Em “Vendem-se livros usados”, qual é a função do “se”?'))) and statement='Em “Vendem-se livros usados”, qual é a função do “se”?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Relacione a distância total ao tempo total, cuidando das unidades.','Taxa média de deslocamento na situação apresentada.','["Velocidade média é distância dividida pelo tempo: 120 ÷ 2 = 60 km/h."]'::jsonb,'["30 km/h corresponderia a percorrer 60 km em 2 h.","120 ÷ 2 = 60 km/h.","90 km/h durante 2 h daria 180 km.","Multiplicar distância por tempo não calcula velocidade média."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Taxa média de deslocamento na situação apresentada."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Um carro percorre 120 km em 2 horas. Qual é sua velocidade média?'))) and statement='Um carro percorre 120 km em 2 horas. Qual é sua velocidade média?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Isole a aceleração na relação entre força resultante e massa.','Segunda lei de Newton: F = m a.','["Pela segunda lei de Newton, F = ma.","Assim, a = 12/3 = 4 m/s²."]'::jsonb,'["3 é o valor da massa, não da aceleração.","a = 12 ÷ 3 = 4 m/s².","Subtrair massa de força mistura grandezas incompatíveis.","Multiplicar força por massa não isola a aceleração."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Segunda lei de Newton: F = m a."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Uma força resultante de 12 N atua em um corpo de 3 kg. Qual é a aceleração?'))) and statement='Uma força resultante de 12 N atua em um corpo de 3 kg. Qual é a aceleração?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Identifique massa, gravidade e altura; a energia depende das três grandezas.','Energia potencial gravitacional próxima à superfície terrestre.','["A energia potencial gravitacional é mgh = 2 × 10 × 5 = 100 J."]'::jsonb,'["O valor 10 não inclui os três fatores m, g e h.","Elevar a altura ao quadrado não faz parte de mgh.","50 corresponde a gh; falta multiplicar pela massa.","2 × 10 × 5 = 100 J."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Energia potencial gravitacional próxima à superfície terrestre."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Um corpo de 2 kg está a 5 m de altura. Adote g = 10 m/s². Qual é sua energia potencial gravitacional?'))) and statement='Um corpo de 2 kg está a 5 m de altura. Adote g = 10 m/s². Qual é sua energia potencial gravitacional?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Partida do repouso elimina o termo da velocidade inicial; lembre que o tempo aparece ao quadrado.','Deslocamento no movimento uniformemente acelerado.','["Para velocidade inicial nula, Δs = at²/2 = 2 × 36 / 2 = 36 m."]'::jsonb,'["a × t calcula a variação de velocidade, não o deslocamento.","18 deixa de considerar corretamente a aceleração de 2 m/s².","Δs = 2 × 6² ÷ 2 = 36 m.","72 omite a divisão por 2."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Deslocamento no movimento uniformemente acelerado."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Um corpo parte do repouso com aceleração constante de 2 m/s². Qual é o deslocamento após 6 s?'))) and statement='Um corpo parte do repouso com aceleração constante de 2 m/s². Qual é o deslocamento após 6 s?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Na lei de Ohm, isole a corrente e verifique a ordem da divisão.','Lei de Ohm: tensão = resistência × corrente.','["Pela lei de Ohm, I = V/R = 12/6 = 2 A."]'::jsonb,'["0,5 resulta da divisão inversa, R/V.","12 ÷ 6 = 2 A.","6 é a resistência, não a corrente.","Multiplicar V por R não calcula a corrente."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Lei de Ohm: tensão = resistência × corrente."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Um resistor de 6 Ω é ligado a 12 V. Qual corrente o atravessa?'))) and statement='Um resistor de 6 Ω é ligado a 12 V. Qual corrente o atravessa?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Some os momentos antes da colisão e use a massa total depois dela.','Conservação do momento linear em colisão perfeitamente inelástica.','["Conservando o momento linear: m × 8 + m × 0 = 2m × v.","Logo v = 4 m/s."]'::jsonb,'["2 m/s daria momento final menor que o inicial.","8m = 2m v, portanto v = 4 m/s.","Manter 8 m/s dobraria o momento porque a massa final dobra.","16 m/s aumentaria ainda mais o momento sem força externa."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Conservação do momento linear em colisão perfeitamente inelástica."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Dois corpos de massas iguais colidem e ficam unidos. Antes, um se movia a 8 m/s e o outro estava parado. Sem força externa resultante, a velocidade final é:'))) and statement='Dois corpos de massas iguais colidem e ficam unidos. Antes, um se movia a 8 m/s e o outro estava parado. Sem força externa resultante, a velocidade final é:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Compare os sinais das cargas das três partículas subatômicas mais comuns.','Cargas elétricas de prótons, nêutrons e elétrons.','["Elétrons têm carga negativa.","Prótons têm carga positiva e nêutrons são eletricamente neutros."]'::jsonb,'["O próton tem carga positiva.","O nêutron é eletricamente neutro.","O elétron tem carga negativa.","O núcleo reúne prótons e nêutrons; sua carga é positiva."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Cargas elétricas de prótons, nêutrons e elétrons."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Qual partícula do átomo possui carga elétrica negativa?'))) and statement='Qual partícula do átomo possui carga elétrica negativa?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Um filtro simples retém partículas de sólido insolúvel, mas não soluto dissolvido.','Separação de mistura heterogênea sólido-líquido.','["A areia é um sólido insolúvel na água, retido pelo filtro.","O líquido atravessa o material filtrante."]'::jsonb,'["O sal dissolvido atravessa o filtro com a água.","A areia insolúvel é retida; a água atravessa o filtro.","Água e álcool são líquidos miscíveis; filtração simples não os separa.","Uma mistura de gases não é separada por esse processo."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Separação de mistura heterogênea sólido-líquido."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Qual mistura pode ser separada por filtração simples?'))) and statement='Qual mistura pode ser separada por filtração simples?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Converta o volume para litros antes de dividir a massa do soluto pelo volume da solução.','Concentração comum: C = m/V.','["500 mL = 0,5 L.","A concentração é massa por volume: 10/0,5 = 20 g/L."]'::jsonb,'["Multiplicar 10 por 0,5 não calcula concentração.","10 g/L desconsidera que o volume é meio litro.","500 mL = 0,5 L; 10/0,5 = 20 g/L.","50 g/L corresponderia a 10 g em 0,2 L."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Concentração comum: C = m/V."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Uma solução contém 10 g de soluto em 500 mL de solução. Qual sua concentração comum?'))) and statement='Uma solução contém 10 g de soluto em 500 mL de solução. Qual sua concentração comum?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Compare apenas os coeficientes do hidrogênio e da água; o oxigênio está em excesso.','Proporção em mols dada pelos coeficientes estequiométricos.','["A proporção estequiométrica entre H₂ e H₂O é 2:2, ou 1:1.","Portanto, formam-se 3 mols de água."]'::jsonb,'["1 mol não preserva a relação 2:2 entre H₂ e H₂O.","Dividir por 2 confunde a proporção H₂:O₂ com H₂:H₂O.","A razão H₂:H₂O é 1:1, formando 3 mols de água.","Multiplicar por 2 ignora que o reagente também tem coeficiente 2."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Proporção em mols dada pelos coeficientes estequiométricos."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Na reação 2 H₂ + O₂ → 2 H₂O, quantos mols de água podem ser formados a partir de 3 mols de H₂ e O₂ em excesso?'))) and statement='Na reação 2 H₂ + O₂ → 2 H₂O, quantos mols de água podem ser formados a partir de 3 mols de H₂ e O₂ em excesso?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Compare o pH informado com o valor de neutralidade nessa temperatura.','Classificação ácido-base pelo pH a 25 °C.','["A 25 °C, soluções com pH inferior a 7 são ácidas.","pH não informa se a solução está saturada."]'::jsonb,'["pH 3 é menor que 7: solução ácida.","Neutralidade corresponde a pH 7 nessa temperatura.","Solução básica tem pH maior que 7 a 25 °C.","pH não determina se a solução está saturada."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Classificação ácido-base pelo pH a 25 °C."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Uma solução aquosa a 25 °C tem pH 3. Ela é:'))) and statement='Uma solução aquosa a 25 °C tem pH 3. Ela é:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Considere uma compressão a temperatura constante e compare os coeficientes dos gases nos dois lados.','Resposta do equilíbrio gasoso à compressão, pelo princípio de Le Chatelier.','["Pelo princípio de Le Chatelier, o sistema favorece a diminuição do número de partículas gasosas para contrapor a compressão."]'::jsonb,'["Mais mols de gás não se opõem à compressão.","Quando os lados têm quantidades gasosas diferentes, a compressão favorece o lado com menos mols.","O critério é o número de mols gasosos, não a massa molar.","A questão trata de pressão; não há aumento obrigatório de temperatura."]'::jsonb,'["Aplicar uma operação sem verificar a relação entre as grandezas e as condições do enunciado."]'::jsonb,'["Resposta do equilíbrio gasoso à compressão, pelo princípio de Le Chatelier."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Em um equilíbrio gasoso, aumentar a pressão favorece o lado com:'))) and statement='Em um equilíbrio gasoso, aumentar a pressão favorece o lado com:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Pense na estrutura que lê o RNA mensageiro e reúne aminoácidos.','Tradução e síntese proteica.','["Ribossomos traduzem o RNA mensageiro, unindo aminoácidos para formar proteínas."]'::jsonb,'["Ribossomos participam diretamente da tradução.","Lisossomos atuam principalmente na digestão intracelular.","Centríolos participam da organização de microtúbulos.","Vacúolos têm funções como armazenamento e regulação osmótica."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Tradução e síntese proteica."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Qual organela é responsável principalmente pela síntese de proteínas?'))) and statement='Qual organela é responsável principalmente pela síntese de proteínas?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Considere em que forma a energia fica armazenada nos compostos orgânicos produzidos.','Transformação de energia na fotossíntese.','["A energia luminosa é utilizada para produzir compostos orgânicos que armazenam energia química."]'::jsonb,'["Fotossíntese não é uma reação nuclear.","Os compostos orgânicos armazenam energia química.","A produção de som não é o principal resultado energético.","Não há conversão principal em energia de posição gravitacional."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Transformação de energia na fotossíntese."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Na fotossíntese, plantas convertem energia luminosa principalmente em:'))) and statement='Na fotossíntese, plantas convertem energia luminosa principalmente em:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Monte as combinações dos gametas A e a de cada progenitor.','Segregação de alelos em um cruzamento monohíbrido.','["As combinações possíveis são AA, Aa, Aa e aa.","Uma em quatro é aa: 25%."]'::jsonb,'["Cada progenitor pode fornecer a; o genótipo aa é possível.","Um dos quatro resultados do quadro de Punnett é aa.","50% corresponde aos heterozigotos, não a aa.","75% pode representar o fenótipo dominante sob dominância completa, não o genótipo aa."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Segregação de alelos em um cruzamento monohíbrido."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('No cruzamento Aa × Aa, qual é a probabilidade de um descendente aa?'))) and statement='No cruzamento Aa × Aa, qual é a probabilidade de um descendente aa?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Observe que o enunciado destaca um evento aleatório, não uma vantagem adaptativa.','Efeito gargalo e amostragem aleatória de alelos.','["O efeito gargalo é um caso de deriva genética: frequências alélicas mudam por amostragem aleatória em uma população reduzida."]'::jsonb,'["O efeito gargalo é um caso de deriva genética.","Mutações não surgem dirigidas pela necessidade da população.","Uso e desuso não explica amostragem aleatória de alelos.","Não há escolha humana de indivíduos reprodutores na situação."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Efeito gargalo e amostragem aleatória de alelos."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Uma população sofre redução drástica por um evento aleatório, alterando frequências alélicas. Esse fenômeno é um exemplo de:'))) and statement='Uma população sofre redução drástica por um evento aleatório, alterando frequências alélicas. Esse fenômeno é um exemplo de:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Procure quem produz matéria orgânica a partir de uma fonte externa de energia.','Fluxo de energia e níveis tróficos.','["Produtores, como plantas e algas, convertem energia externa em matéria orgânica que sustenta a cadeia alimentar."]'::jsonb,'["Decompositores usam matéria orgânica já produzida.","Consumidores secundários obtêm energia de outros seres vivos.","Produtores incorporam energia externa à matéria orgânica.","Parasitas dependem de um hospedeiro, não cumprem essa função geral."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Fluxo de energia e níveis tróficos."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Em uma cadeia alimentar, qual grupo introduz energia química produzida a partir de fontes externas, como a luz?'))) and statement='Em uma cadeia alimentar, qual grupo introduz energia química produzida a partir de fontes externas, como a luz?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Aplique o pareamento de bases e mantenha as duas fitas em sentidos opostos.','Complementaridade e antiparalelismo do DNA.','["As fitas são antiparalelas e as bases se pareiam A–T e G–C.","Assim, a complementar é 3′-TACG-5′."]'::jsonb,'["As bases complementam, mas o sentido indicado é paralelo.","A–T e G–C, em sentido antiparalelo: 3′-TACG-5′.","A sequência foi repetida, sem complementar as bases.","Uracila é própria do RNA; além disso, a orientação está incorreta."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Complementaridade e antiparalelismo do DNA."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Uma fita de DNA tem sequência 5′-ATGC-3′. Qual é a fita complementar corretamente orientada?'))) and statement='Uma fita de DNA tem sequência 5′-ATGC-3′. Qual é a fita complementar corretamente orientada?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Diferencie a abolição geral das leis anteriores que tiveram alcance parcial.','Processo histórico de abolição legal da escravidão no Brasil.','["A Lei Áurea aboliu legalmente a escravidão em 13 de maio de 1888.","A Lei do Ventre Livre foi anterior e teve alcance limitado."]'::jsonb,'["A Lei Áurea, de 1888, aboliu legalmente a escravidão.","A Lei de Terras trata do acesso à propriedade da terra.","Leis de cotas não são a lei abolicionista de 1888.","A Lei do Ventre Livre, de 1871, teve alcance parcial e anterior."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Processo histórico de abolição legal da escravidão no Brasil."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('A abolição legal da escravidão no Brasil ocorreu com qual lei?'))) and statement='A abolição legal da escravidão no Brasil ocorreu com qual lei?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Compare a produção artesanal com mudanças técnicas e na organização do trabalho.','Mecanização e sistema fabril na Revolução Industrial.','["A mecanização e o sistema fabril transformaram a produção e as relações de trabalho, com destaque inicial para a indústria têxtil."]'::jsonb,'["O movimento central foi ampliar a mecanização, não retornar ao artesanato.","Máquinas e fábricas transformaram a produção e o trabalho.","A industrialização favoreceu o crescimento urbano, não o fim das cidades.","A energia a vapor teve papel importante na industrialização."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Mecanização e sistema fabril na Revolução Industrial."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('A Revolução Industrial iniciada na Inglaterra caracterizou-se principalmente por:'))) and statement='A Revolução Industrial iniciada na Inglaterra caracterizou-se principalmente por:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Relacione o movimento à crítica da autoridade e à valorização da investigação racional.','Razão, crítica e direitos no pensamento iluminista.','["Pensadores iluministas valorizavam a razão e questionavam privilégios e formas tradicionais de autoridade."]'::jsonb,'["A defesa irrestrita do absolutismo contraria críticas iluministas ao poder arbitrário.","Razão e crítica aos privilégios são aspectos centrais do movimento.","A investigação científica foi valorizada, não rejeitada por completo.","Restaurar o feudalismo não era seu objetivo central."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Razão, crítica e direitos no pensamento iluminista."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Uma característica central do Iluminismo europeu foi:'))) and statement='Uma característica central do Iluminismo europeu foi:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Relacione o texto constitucional à ampliação de direitos e à participação política.','Direitos e redemocratização na Constituição de 1988.','["A Constituição de 1988 ampliou direitos civis, políticos e sociais após o regime militar, consolidando instituições democráticas."]'::jsonb,'["A Constituição assegurou participação eleitoral, não extinguiu eleições diretas.","O texto ampliou direitos e garantias democráticas.","A forma republicana foi mantida.","A liberdade de associação foi garantida, não proibida em geral."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Direitos e redemocratização na Constituição de 1988."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('A Constituição brasileira de 1988 é associada à redemocratização porque:'))) and statement='A Constituição brasileira de 1988 é associada à redemocratização porque:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Pense nos polos de poder que se consolidaram após a Segunda Guerra Mundial.','Bipolaridade e disputas políticas da Guerra Fria.','["Estados Unidos e União Soviética lideraram blocos rivais em disputas políticas, econômicas, militares e ideológicas."]'::jsonb,'["A rivalidade colonial ibérica pertence a outro contexto histórico.","Estados Unidos e União Soviética lideraram os principais blocos rivais.","Brasil e Argentina não eram os dois polos da Guerra Fria.","França e Itália não formaram os dois blocos centrais desse conflito."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Bipolaridade e disputas políticas da Guerra Fria."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('A Guerra Fria foi marcada principalmente pela rivalidade entre:'))) and statement='A Guerra Fria foi marcada principalmente pela rivalidade entre:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Considere quem produziu a fonte, em que momento, para quem e com qual finalidade.','Análise crítica de fontes históricas.','["Fontes são produzidas em situações específicas.","Autoria, finalidade e contexto ajudam a interpretar seus significados e limites."]'::jsonb,'["Fontes têm perspectivas e limites; sua neutralidade não pode ser presumida.","O contexto ajuda a avaliar interesses, perspectivas e limites.","Autoria é parte importante da análise, não deve ser ignorada.","A análise contextual qualifica as evidências; não as substitui por opinião."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Análise crítica de fontes históricas."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Ao analisar uma fonte histórica, por que é necessário considerar seu contexto de produção?'))) and statement='Ao analisar uma fonte histórica, por que é necessário considerar seu contexto de produção?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Procure a linha de latitude zero, e não um meridiano.','Paralelos, meridianos e hemisférios terrestres.','["A Linha do Equador corresponde à latitude 0° e separa os hemisférios Norte e Sul."]'::jsonb,'["O Trópico de Capricórnio está no hemisfério Sul.","Greenwich é referência de longitude, não a divisão Norte–Sul.","O Equador tem latitude zero e separa Norte e Sul.","O Círculo Polar Ártico fica no hemisfério Norte."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Paralelos, meridianos e hemisférios terrestres."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Qual linha imaginária divide a Terra em hemisférios Norte e Sul?'))) and statement='Qual linha imaginária divide a Terra em hemisférios Norte e Sul?' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Multiplique a distância do mapa pelo denominador da escala e só então converta a unidade.','Escala cartográfica e conversão de centímetros em quilômetros.','["Cada centímetro representa 100.000 cm, ou 1 km.","Logo, 2 cm representam 2 km."]'::jsonb,'["200 m corresponde a 20.000 cm; falta um fator 10.","1 km corresponde a apenas 1 cm nessa escala.","2 × 100.000 cm = 200.000 cm = 2 km.","20 km acrescenta um fator 10 indevido na conversão."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Escala cartográfica e conversão de centímetros em quilômetros."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Em um mapa de escala 1:100.000, uma distância de 2 cm representa:'))) and statement='Em um mapa de escala 1:100.000, uma distância de 2 cm representa:' on conflict(question_id) do nothing;
insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Observe que importa a participação da população urbana no total, não só o crescimento de uma cidade.','Urbanização como transformação da distribuição populacional.','["Urbanização é o aumento da participação da população urbana no total populacional."]'::jsonb,'["Urbanização é o aumento da proporção de habitantes em áreas urbanas.","Desertificação envolve degradação de terras em regiões secas.","Intemperismo envolve alteração e desagregação de rochas.","Sedimentação é a deposição de materiais transportados."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Urbanização como transformação da distribuição populacional."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('O processo de crescimento da proporção da população que vive em cidades é chamado de:'))) and statement='O processo de crescimento da proporção da população que vive em cidades é chamado de:' on conflict(question_id) do nothing;
