insert into private.question_pedagogy(question_id,hint,key_concept,solution_steps,option_explanations,common_mistakes,prerequisites,skills) select id,'Relacione a base às faixas etárias jovens e o topo às mais idosas.','Estrutura etária e transição demográfica.','["A base estreita indica menos nascimentos relativos, e o topo mais largo indica maior participação de idosos, associada ao envelhecimento."]'::jsonb,'["Alta natalidade recente tenderia a ampliar a base, não estreitá-la.","Menor base e maior proporção idosa indicam menor natalidade e envelhecimento.","O padrão é compatível com fases avançadas da transição demográfica.","O crescimento natural não precisa ser elevado nesse padrão."]'::jsonb,'["Escolher por uma palavra isolada, sem relacionar a alternativa ao contexto do enunciado."]'::jsonb,'["Estrutura etária e transição demográfica."]'::jsonb,'["Interpretar o enunciado","Justificar a escolha"]'::jsonb from public.questions where fingerprint=md5(lower(trim('Uma pirâmide etária com base estreita e maior proporção de idosos indica, em geral:'))) and statement='Uma pirâmide etária com base estreita e maior proporção de idosos indica, em geral:' on conflict(question_id) do nothing;
